#ifndef TILES_H_COURIER
#define TILES_H_COURIER

/* Tile indices in assets/tileset.gif (generated by tools/make_tileset.py) */

#define T_EMPTY        0

/* L0 backdrop */
#define T_BG           1
#define T_BG_H         2
#define T_BG_V         3
#define T_BG_X         4
#define T_BG_CHIP      5   // 5..8, a 2x2 chip silhouette

/* L1 room tiles */
#define T_BOARD_TOP    16  // 16..17 solid with a lit top edge
#define T_BOARD        18  // 18..20 solid fill
#define T_ONEWAY       21
#define T_LADDER       22
#define T_SPIKES       23
#define T_DOOR         24
#define T_SOCKET       25
#define T_SOCKET_FULL  26
#define T_SWITCH       27
#define T_SWITCH_ON    28
#define T_GATE         29
#define T_GATE_OPEN    30
#define T_HUD          31
#define T_CPU          33  // 33..36, 2x2
#define T_LADDER_TOP   37  // ladder + one-way lip
#define T_CONV_L       50  // conveyor belts (solid), animated by rotating their pixels (anim.bin)
#define T_CONV_R       51
#define T_FAN          52  // fan grille in the floor (solid), blowing
#define T_FAN_OFF      53
#define T_WIND         54  // updraft above a running fan, animated

/* sprites */
#define T_BOT_IDLE     40
#define T_BOT_RUN      41
#define T_BOT_JUMP     42
#define T_BOT_CARRY    43
#define T_BIT          44  // 44..45
#define T_DRONE        46  // 46..47
#define T_SPARK        48  // 48..49

/* zone themes 1..3: 5 board tiles (like T_BOARD_TOP..T_BOARD + 2) then 8 backdrop tiles (like T_BG..T_BG_CHIP + 3);
 * theme 0 is the tiles above */
#define T_THEME        112  // theme t at T_THEME + (t - 1) * 16, its backdrop 8 tiles further

/* font: '0'..'9', 'A'..'Z', '/', '!', '-', ':' */
#define T_FONT_DIGITS  64
#define T_FONT_ALPHA   74
#define T_FONT_SLASH   100
#define T_FONT_BANG    101
#define T_FONT_DASH    102
#define T_FONT_COLON   103

#endif
